import pandas as pd
from collections import Counter
from typing import List, Tuple

from solver import Algorithm


class Evolved(Algorithm):
    """Optimize character-prefix reuse with global layouts and bounded exact row ascent."""

    def __init__(self, df: pd.DataFrame = None):
        """Store the optional dataframe and initialize shape metadata."""
        self.df = df
        self.num_rows = 0
        self.num_cols = 0

    @staticmethod
    def _text(value) -> str:
        """Serialize one scalar exactly for scoring, mapping scalar missing values to empty text."""
        try:
            missing = pd.isna(value)
            if not hasattr(missing, "__len__") and bool(missing):
                return ""
        except Exception:
            pass
        return str(value)

    @staticmethod
    def _lcp(left: str, right: str) -> int:
        """Return the exact common-prefix length using binary-search slicing."""
        limit = min(len(left), len(right))
        if limit == 0 or left[0] != right[0]:
            return 0

        low, high = 1, limit
        while low < high:
            middle = (low + high + 1) // 2
            if left[:middle] == right[:middle]:
                low = middle
            else:
                high = middle - 1
        return low

    @classmethod
    def _reuse(cls, strings: List[str]) -> int:
        """Compute exact ideal Trie reuse as LCP lengths of sorted adjacent strings."""
        if len(strings) < 2:
            return 0

        ordered = sorted(strings)
        total = 0
        previous = ordered[0]

        for current in ordered[1:]:
            if current == previous:
                total += len(current)
            else:
                total += cls._lcp(previous, current)
            previous = current

        return total

    @staticmethod
    def _merge(columns, order, col_merge):
        """Make requested merge groups contiguous while preserving their proposed order."""
        if not col_merge:
            return list(order)

        position = {column: index for index, column in enumerate(order)}
        owners = {}
        claimed = set()

        for requested in col_merge:
            group = [
                column for column in order
                if column in requested and column not in claimed
            ]
            if not group:
                continue

            group.sort(key=position.__getitem__)
            for column in group:
                owners[column] = group
                claimed.add(column)

        result = []
        emitted = set()

        for column in order:
            if column in emitted:
                continue

            group = owners.get(column)
            if group is None:
                result.append(column)
                emitted.add(column)
            else:
                result.extend(group)
                emitted.update(group)

        return result

    @classmethod
    def _normalize(cls, columns, integer_order, col_merge):
        """Convert integer positions into a valid merge-aware integer permutation."""
        proposed = [columns[index] for index in integer_order]
        merged = cls._merge(columns, proposed, col_merge)
        lookup = {column: index for index, column in enumerate(columns)}
        return [lookup[column] for column in merged]

    @staticmethod
    def _serialize(text, orders):
        """Serialize every row using its row-specific integer column permutation."""
        return [
            "".join(text[row][column] for column in orders[row])
            for row in range(len(orders))
        ]

    def _global_candidates(self, text, columns, col_merge):
        """Build frequency-ranked and partial-prefix-ranked global permutations."""
        rows = len(text)
        width = len(columns)
        whole_mass = []
        prefix_mass = []

        for column in range(width):
            counts = Counter(text[row][column] for row in range(rows))
            whole = sum(
                len(value) * count * (count - 1)
                for value, count in counts.items()
            )
            whole_mass.append((whole, len(counts)))

            prefixes = Counter()
            for value, count in counts.items():
                for size in range(1, min(8, len(value)) + 1):
                    prefixes[value[:size]] += count

            partial = sum(
                len(value) * count * (count - 1)
                for value, count in prefixes.items()
            )
            prefix_mass.append((partial, len(prefixes)))

        frequency = sorted(
            range(width),
            key=lambda column: (
                -whole_mass[column][0],
                whole_mass[column][1],
                column,
            ),
        )

        prefix = sorted(
            range(width),
            key=lambda column: (
                -prefix_mass[column][0],
                prefix_mass[column][1],
                -whole_mass[column][0],
                column,
            ),
        )

        return [
            self._normalize(columns, frequency, col_merge),
            self._normalize(columns, prefix, col_merge),
        ]

    @staticmethod
    def _units(order, width, col_merge):
        """Convert an integer permutation into indivisible merge-aware integer units."""
        if not col_merge:
            return [[column] for column in order]

        # Merge specifications use dataframe column labels.
        label_to_index = {label: index for index, label in enumerate(range(width))}
        # The caller supplies integer-normalized merge groups when available.
        # For ordinary labelled groups, this method is bypassed by _merge_units.
        groups = []
        claimed = set()
        position = {column: index for index, column in enumerate(order)}

        for requested in col_merge:
            members = []
            for item in requested:
                if isinstance(item, int) and 0 <= item < width:
                    members.append(item)
            members = [item for item in members if item not in claimed]
            if members:
                members.sort(key=position.__getitem__)
                groups.append(members)
                claimed.update(members)

        for column in order:
            if column not in claimed:
                groups.append([column])

        groups.sort(key=lambda group: min(position[column] for column in group))
        return groups

    @staticmethod
    def _flatten(units):
        """Flatten merge-aware integer units into one integer permutation."""
        return [column for unit in units for column in unit]

    def _merge_units(self, order, columns, col_merge):
        """Build merge-aware units while correctly translating public column labels."""
        if not col_merge:
            return [[column] for column in order]

        lookup = {label: index for index, label in enumerate(columns)}
        translated = []

        for requested in col_merge:
            group = []
            for item in requested:
                if item in lookup:
                    group.append(lookup[item])
                elif isinstance(item, int) and 0 <= item < len(columns):
                    group.append(item)
            translated.append(group)

        position = {column: index for index, column in enumerate(order)}
        units = []
        claimed = set()

        for requested in translated:
            group = [
                column for column in order
                if column in requested and column not in claimed
            ]
            if group:
                group.sort(key=position.__getitem__)
                units.append(group)
                claimed.update(group)

        for column in order:
            if column not in claimed:
                units.append([column])

        units.sort(key=lambda group: min(position[column] for column in group))
        return units

    def _refine_rows(self, text, columns, col_merge, seed_orders, seed_serialized):
        """Perform bounded exact whole-batch row-local swap ascent.

        The best global layout is copied.  Rows are prioritized by serialized
        length and repeated-string mass.  For a bounded subset, exchanges
        between leading and trailing merge-aware units are tested against the
        exact complete sorted-LCP objective.  Only improving swaps are kept.
        """
        rows = len(text)
        width = len(columns)

        if rows < 2 or width < 2:
            return seed_orders, seed_serialized

        orders = [list(order) for order in seed_orders]
        serialized = list(seed_serialized)
        current_score = self._reuse(serialized)

        counts = Counter(serialized)
        priority = sorted(
            range(rows),
            key=lambda row: (
                -len(serialized[row]) * max(1, counts[serialized[row]] - 1),
                -len(serialized[row]),
                row,
            ),
        )

        # Keep the exact objective bounded; this is intentionally much smaller
        # than a full row-by-row search.
        selected = priority[:min(24, rows)]

        for row in selected:
            units = self._merge_units(orders[row], columns, col_merge)
            if len(units) < 2:
                continue

            head = list(range(min(4, len(units))))
            tail = list(range(max(0, len(units) - 4), len(units)))

            accepted = 0
            for left in head:
                if accepted >= 2:
                    break

                tested = 0
                for right in tail:
                    if right <= left or tested >= 6:
                        continue
                    tested += 1

                    trial_units = [unit[:] for unit in units]
                    trial_units[left], trial_units[right] = (
                        trial_units[right],
                        trial_units[left],
                    )
                    trial_order = self._flatten(trial_units)

                    trial_string = "".join(
                        text[row][column] for column in trial_order
                    )
                    trial_serialized = list(serialized)
                    trial_serialized[row] = trial_string

                    trial_score = self._reuse(trial_serialized)
                    if trial_score > current_score:
                        orders[row] = trial_order
                        serialized = trial_serialized
                        current_score = trial_score
                        units = trial_units
                        accepted += 1
                        break

        return orders, serialized

    def reorder(
        self,
        df: pd.DataFrame,
        early_stop: int = 0,
        row_stop: int = None,
        col_stop: int = None,
        col_merge=[],
        one_way_dep=[],
        distinct_value_threshold=0.8,
        parallel=True,
    ) -> Tuple[pd.DataFrame, List[List[str]]]:
        """Return the best bounded global layout after exact row-local refinement."""
        self.df = df
        self.num_rows, self.num_cols = df.shape

        rows, width = df.shape
        columns = list(df.columns)

        if rows == 0 or width == 0:
            return df.copy(), [[] for _ in range(rows)]

        raw = df.to_numpy(dtype=object, copy=True)
        text = [
            [self._text(raw[row, column]) for column in range(width)]
            for row in range(rows)
        ]

        global_orders = self._global_candidates(
            text,
            columns,
            col_merge,
        )

        candidates = []
        for order in global_orders:
            orders = [order[:] for _ in range(rows)]
            serialized = self._serialize(text, orders)
            candidates.append((
                self._reuse(serialized),
                orders,
                serialized,
            ))

        candidates.sort(key=lambda item: item[0], reverse=True)
        best_score, best_orders, best_serialized = candidates[0]

        refined_orders, refined_serialized = self._refine_rows(
            text,
            columns,
            col_merge,
            best_orders,
            best_serialized,
        )
        refined_score = self._reuse(refined_serialized)

        if refined_score >= best_score:
            best_orders = refined_orders
            best_serialized = refined_serialized

        row_order = sorted(
            range(rows),
            key=lambda row: best_serialized[row],
        )

        output = [
            [raw[row, column] for column in best_orders[row]]
            for row in row_order
        ]
        orderings = [
            [columns[column] for column in best_orders[row]]
            for row in row_order
        ]

        result = pd.DataFrame(
            output,
            columns=columns,
            index=df.index.take(row_order),
            dtype=object,
        )
        return result, orderings

